SELECT EXISTS (
    SELECT 1
    FROM coeat_request c
    WHERE c.user_id = #{userId}
      AND c.coeat_id = #{coeatId}
)

mapper.update:
UPDATE coeat_request r
JOIN coeat c ON r.coeat_id = c.id
SET r.status = #{coeatRequest.status}
WHERE r.coeat_id = #{coeatId}
    AND r.user_id = #{coeatRequest.userId}
    AND c.status = 'OPEN'
    AND r.status IN ('PENDING', 'REJECTED')
    AND (
        (#{coeatRequest.status} = 'APPROVED'
        AND (SELECT COUNT(*)
             FROM coeat_request
             WHERE coeat_id = #{coeatId}
                AND status = 'APPROVED') < c.capacity)
        OR (#{coeatRequest.status} <> 'APPROVED')
    )

UPDATE coeat_request
SET status = 'CANCELLED'
WHERE coeat_id = #{coeatId}
  AND user_id = #{userId}
  AND status <> 'CANCELLED'
